def label(n,t):return f'<p class="eyebrow"><span>{n}</span><span>{t}</span></p>'
def btn(u,t,secondary=False):return f'<a class="button {"secondary" if secondary else "primary"}" href="{u}">{t}<span aria-hidden="true">↗</span></a>'
def intro(n,k,t,d,a=''):return f'<section class="page-intro wrap">{label(n,k)}<h1>{t}</h1><p class="intro-text">{d}</p><div class="actions">{a}</div></section>'
def head(n,k,t,d=''):return f'<div class="section-head">{label(n,k)}<div><h2>{t}</h2>{("<p>"+d+"</p>") if d else ""}</div></div>'
