def fig(src,alt,cap,eager=False,id=''):
 w,h=DIMS[src];kind='phone-display' if w<h else 'screen-display';url='/assets/'+src
 return f'<figure class="{kind}"><a class="image-link" href="{url}" data-lightbox data-caption="{escape(cap,quote=True)}" aria-label="查看大图：{escape(alt,quote=True)}"><img '+(f'id="{id}" ' if id else '')+f'src="{url}" alt="{escape(alt,quote=True)}" width="{w}" height="{h}" loading="{"eager" if eager else "lazy"}" decoding="async"></a><figcaption>{cap}<span>点击查看大图 ↗</span></figcaption></figure>'
def cards(items,cls='feature-grid'):
 return f'<div class="{cls}">'+''.join(f'<article class="feature-card"><span class="item-number">{n}</span><h3>{t}</h3><p>{d}</p></article>' for n,t,d in items)+'</div>'
