pricing+='<section class="wrap pricing-types"><article><span class="eyebrow">按需购买</span><h2>Relic Token</h2><p>产品内使用额度。正式开放时，将明确数量、有效期、适用客户端，以及聊天与蒸馏各自的扣量方式。</p><span class="unavailable">正式价格待发布</span></article><article><span class="eyebrow">周期权益</span><h2>月套餐</h2><p>周期内的套餐权益，与单独购买的额度分别说明。正式开放时会列明当期权益、有效期、续费与取消方式。</p><span class="unavailable">正式权益待发布</span></article></section><section class="wrap section-space faq"><h2>购买开放前，先了解这些区别。</h2>'
for q,a in [
 ('Relic Token 等于模型供应商的 Token 吗？','不等于。Relic Token 是产品计量单位，不能直接理解为字数或模型供应商原始 Token。正式换算规则会与后台账本保持一致，并在购买前公开说明。'),
 ('聊天与蒸馏怎样扣量？','两类任务分别计量。正式开放前需要核实成功、失败、取消和超限的结算规则；消耗超过已确认范围时，应先取得确认。当前没有可付费的网页任务。'),
 ('购买后可以在哪些客户端使用？','官网购买尚未开放，目前不作跨端可用性的销售承诺。现有 iOS 与小程序正在验证绑定账户下的共享角色，历史独立余额不会自动合并；正式购买页将明确每种额度的适用客户端。'),
 ('会自动续费吗？如何取消？','官网当前没有收费或自动续费。已有 Apple 订阅可在 <a href="https://apps.apple.com/account/subscriptions">Apple 订阅管理</a>查看和取消，以原购买渠道显示的状态为准。'),
 ('订单或退款怎样处理？','官网暂无已生效订单。现有渠道订单请按原购买渠道的流程查询和申请退款。也可通过<a href="/contact/">企业微信</a>咨询产品问题；不要发送密码、验证码或完整支付凭据。'),
]:pricing+=f'<details><summary>{q}</summary><p>{a}</p></details>'
pricing+='</section>'
page('relic/pricing/index.html','Relic 价格与购买状态','Relic 官网购买暂未开放。了解产品额度、月套餐、计量规则、跨端账户和已有渠道订单处理方式。',pricing,'products','relic-page')

account=intro('RELIC','ACCOUNT','同一个你，<br>同一份角色与记忆。','官网登录暂未开放。现有账户仍在原客户端使用，官网不会要求你另建一套与产品割裂的账户。')
account+='<section class="wrap notice"><span class="status muted">网页登录暂未开放</span><h2>请在已有客户端查看账户。</h2><p>当前官网无法展示适用余额、套餐权益和订单。请使用已有客户端的登录与账号管理。</p><p>iOS 与微信小程序的绑定须经双方验证，历史独立资料和余额不会自动合并。素材上传的一次性授权仅用于上传素材，不能登录账户或付款。</p><p>不要把登录验证码或上传授权链接发送给他人，也不要用它们作为付款证明。</p><div class="actions">'+btn('/relic/pricing/','价格与购买状态',True)+btn('/support/#relic','Relic 使用帮助',True)+'</div></section>'
page('account/index.html','Relic 账户入口状态','Relic 网页登录暂未开放。请在已有客户端查看账户、角色和可用权益；官网没有余额或订单查询功能。',account,'products','relic-page')

support=intro('SUPPORT','PRODUCT HELP','先找到，<br>你需要的那份帮助。','安装、权限、账户和使用说明按产品整理。需要进一步沟通时，可以通过企业微信联系。')
support+='<section class="wrap support-grid">'
for id,n,t,d,links in [
 ('meow','01','喵喵键盘','安装启用、中文输入、猫猫主题、颜文字、会员恢复与完全访问权限。',[('/meow/support.html','安装与使用帮助'),('/meow/privacy.html','产品隐私政策'),('/downloads/#meow','选择 App Store 地区')]),
 ('relic','02','Relic','获授权素材导入、角色资料、可编辑记忆与账户绑定。',[('/support','现有客户端支持页'),('/privacy','Relic 产品隐私说明'),('/relic/pricing/','价格与购买状态')]),
 ('futures','03','Futures Alpha','行情来源、模拟模式、研究功能与当前分发状态。',[('/products/futures-alpha/','产品功能与开发状态'),('/downloads/#futures','公开分发状态')]),
]:
 support+=f'<article class="support-card" id="{id}"><span class="item-number">{n}</span><h2>{t}</h2><p>{d}</p><div class="support-links">'+''.join(f'<a href="{u}">{text} <span aria-hidden="true">↗</span></a>' for u,text in links)+'</div></article>'
support+='</section><section class="wrap section-space prose"><h2>准备问题描述时，保护好自己的资料。</h2><p>记录产品版本、系统版本和操作步骤，尽量用虚构短句复现。截图请遮挡联系人、通知、账户和私人对话；不要发送密码、验证码或完整聊天记录。</p><p>可以通过<a href="/contact/">联系页的企业微信</a>咨询。官方邮箱收信能力尚待验证。已有订阅和订单请使用原购买渠道管理。</p></section>'
page('support/index.html','产品支持','喵喵键盘、Relic 与 Futures Alpha 的安装、使用、账户和隐私帮助。进一步咨询可通过 EPIYA 企业微信联系。',support)

terms=intro('LEGAL','TERMS','服务说明。','更新于 2026 年 11 月 4 日。')+'<section class="wrap prose legal"><h2>网站与服务范围</h2><p>本站由杭州壹湃科技有限公司运营，用于介绍 EPIYA 自有产品、已核实的分发入口、定制开发范围和官方联系渠道状态。具体产品功能及权益以客户端、正式说明与购买渠道为准。定制项目的范围、费用、交付和维护方式需另行确认。</p><h2>购买与分发</h2><p>Relic 官网暂未开放购买或登录，不在本站收费。喵喵键盘通过 Apple App Store 分发，会员价格、试用资格、续订、取消和退款以 Apple 确认页及流程为准。开发测试状态不代表已经正式发布。</p><h2>AI 角色与素材</h2><p>仅使用你有权处理的对话和人物资料，尊重他人的隐私与授权范围。AI 角色并非真人，生成内容可能不准确。网页合成样例用于解释功能，不代表特定真人的言论或实时模型输出。</p><h2>金融研究</h2><p>Futures Alpha 仍在开发，面向研究与模拟。页面展示及策略信号不构成投资建议或收益保证，模拟与历史回放不能当作实盘业绩。</p><h2>品牌与内容</h2><p>Relic 的命名灵感说明不表示与《赛博朋克 2077》游戏官方存在合作或授权。本站不对尚未取得的版权、商标或其他登记作出声明。</p><h2>官方联系状态</h2><p>可通过<a href="/contact/">企业微信</a>联系。contact@epiya.cn 的收信能力尚待验证。现有产品订单及退款请使用原购买渠道；官网没有已生效的 Relic 购买订单。</p></section>'
page('terms.html','服务说明','EPIYA 网站、产品展示、定制开发范围与现有购买渠道的服务说明。',terms)
page('changelog.html','版本与分发记录','EPIYA 产品的正式版本与开发测试状态，分别列出已核实的公开分发情况。',intro('RELEASE NOTES','VERIFIED STATUS','每个版本，<br>讲清实际进度。','以下商品与工程状态于 2026 年 11 月 3 日核验。')+'<section class="wrap prose legal"><h2>喵喵键盘 2.6</h2><p>可查询的正式 App Store 版本。中国大陆商品记录发布日期为 2026-10-27；美国等其他抽查地区为 2026-10-09。支持26键与九宫格中文输入、喵化、颜文字和主题。开发工程 2.6.1 不代表商店已经更新。</p><h2>Relic</h2><p>内部与开发测试阶段，尚无已核实的公开下载入口。页面中的真实开发版截图使用合成资料，标记 build19 或 build20；不作为最新发行版本展示。</p><h2>Futures Alpha 工作台06</h2><p>macOS Apple Silicon 内部开发验证，尚未达到正式公开分发条件。当前不提供历史测试包，实盘通道保持锁定。</p><h2>官网内容更新 · 2026-11-04</h2><p>更新品牌展示、截图布局与定制开发说明。创始人公开署名为 42，企业微信联系入口已提供；官方邮箱收信能力仍待验证。</p><a class="text-link" href="/downloads/">前往下载中心 ↗</a></section>')
page('404.html','页面未找到','这个地址没有对应页面，可返回 EPIYA 首页或查看产品支持。',intro('404','PAGE NOT FOUND','这里还没有页面。','地址可能已经变化。你可以回到首页，或从产品支持找到原来的入口。',btn('/','返回首页')+btn('/support/','产品支持',True)))

# Keep the privacy source and historic App Store-linked policy paths available.
privacy=(R/'tools/privacy-original.txt').read_text(encoding='utf-8')
privacy_body=privacy.split('<div class="wrap prose">',1)[1].split('</div></main>',1)[0]
privacy_body=privacy_body.replace('<p class="meta">更新日期：2026 年 11 月 4 日</p>','')
page('privacy.html','网站隐私说明','EPIYA 公司展示网站的隐私说明、官方联系渠道状态与产品隐私政策入口。',intro('LEGAL','WEBSITE PRIVACY','网站隐私说明。','更新于 2026 年 11 月 4 日。本说明适用于 epiya.cn 公司展示页面。')+'<section class="wrap prose legal">'+privacy_body+'<h2>产品隐私说明入口</h2><p><a href="/meow/privacy.html">喵喵键盘隐私政策</a> · <a href="/privacy">Relic 产品隐私说明</a></p></section>')
paths=sorted('/'+str(p.relative_to(R)) for p in R.rglob('*.html') if '.git' not in p.parts and p.name!='404.html')
(R/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>https://epiya.cn'+p.replace('/index.html','/')+'</loc></url>' for p in paths)+'</urlset>',encoding='utf-8')
(R/'robots.txt').write_text('User-agent: *\nAllow: /\nDisallow: /v1/\nDisallow: /upload\nSitemap: https://epiya.cn/sitemap.xml\n',encoding='utf-8')
print('Built',len(paths)+1,'pages, including three retained legacy Meow pages.')
